package com.campuslostfound.util;
import com.campuslostfound.db.DatabaseManager; import java.io.*; import java.nio.file.*; import java.sql.*;
public class CsvExporter { public void exportItems(Path out)throws SQLException,IOException{Files.createDirectories(out.getParent());String q="SELECT id,user_id,type,title,category,location,item_date,description,status FROM items ORDER BY id";try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery();BufferedWriter w=Files.newBufferedWriter(out)){w.write("id,user_id,type,title,category,location,item_date,description,status");w.newLine();while(r.next()){String[] v={r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9)};for(int i=0;i<v.length;i++){if(i>0)w.write(",");w.write(csv(v[i]));}w.newLine();}}}private String csv(String v){return v==null?"":"\""+v.replace("\"","\"\"")+"\"";}}
